/// <summary>
/// Recurring, throttled check for a Manatime service upgrade and a newer Mynatime release.
/// The network fetch runs after a command (never blocking it) at most once per interval;
/// the notices render from the values stored in the profile, so they show even between checks.
/// </summary>
internal static class VersionCheck
{
    private static readonly TimeSpan SuccessInterval = TimeSpan.FromDays(1);
    private static readonly TimeSpan FailureInterval = TimeSpan.FromHours(1);

    internal enum ManatimeDrift
    {
        None,
        MinorPatch,
        Major,
    }

    /// <summary>
    /// Classifies the seen Manatime version against the version this client validated against.
    /// </summary>
    internal static ManatimeDrift CompareManatime(string? seen, string? expected)
    {
        if (!TryParseVersion(seen, out var s) || !TryParseVersion(expected, out var e) || s <= e)
        {
            return ManatimeDrift.None;
        }

        return s.Major > e.Major ? ManatimeDrift.Major : ManatimeDrift.MinorPatch;
    }

    /// <summary>
    /// True when the automatic check is due (never checked, or the scheduled time has passed).
    /// </summary>
    internal static bool IsDue(MynatimeProfile profile, DateTime nowUtc)
    {
        return profile.NextVersionCheckUtc == null || nowUtc >= profile.NextVersionCheckUtc.Value;
    }

    /// <summary>
    /// Renders the drift/update notices from the values already stored in the profile. No network.
    /// </summary>
    internal static void RenderNotices(IAnsiConsole console, MynatimeProfile profile)
    {
        var drift = CompareManatime(profile.LastAppVersionSeen, ClientConstants.ExpectedManatimeVersion);
        if (drift != ManatimeDrift.None)
        {
            var color = drift == ManatimeDrift.Major ? "red" : CliTheme.Chrome;
            var message = "⚠ Manatime is now " + profile.LastAppVersionSeen
                + " (client validated for " + ClientConstants.ExpectedManatimeVersion + ")";
            console.MarkupLine("[" + color + "]" + Markup.Escape(message) + "[/]");
        }

        if (UpdateChecker.IsNewer(profile.LastKnownReleaseTag, UpdateChecker.GetCurrentVersion()))
        {
            var current = UpdateChecker.GetCurrentVersion() ?? "unknown";
            console.MarkupLine("[yellow]A new Mynatime version is available: "
                + Markup.Escape(profile.LastKnownReleaseTag!) + " (current: " + Markup.Escape(current)
                + "). Run mynatime-update.[/]");
