                profile.LastAppVersionSeen = manatimeTask.Result;
                reached = true;
            }

            if (githubTask.Result != null)
            {
                profile.LastKnownReleaseTag = githubTask.Result;
                reached = true;
            }
        }
        catch
        {
            // best effort: any failure just schedules a sooner retry below
        }
        finally
        {
            profile.NextVersionCheckUtc = NextCheckTime(nowUtc, reached);
        }

        return profile.LastAppVersionSeen != oldSeen || profile.LastKnownReleaseTag != oldTag;
    }

    /// <summary>
    /// When to check next: in a day when the network was reached, in an hour otherwise (so an
    /// offline machine retries hourly rather than on every command).
    /// </summary>
    internal static DateTime NextCheckTime(DateTime nowUtc, bool reached)
    {
        return nowUtc + (reached ? SuccessInterval : FailureInterval);
    }

    private static bool TryParseVersion(string? value, out Version version)
    {
        version = new Version(0, 0);
